feed:
{%- set posts_section = get_section(path="posts/_index.md") -%}
{{ config.title | escape_xml | safe }}
{%- if config.description -%}
{{ config.description | escape_xml | safe }}
{%- endif -%}


Zola
{{ feed_url | safe }}
{%- if last_updated is defined -%}
{{ last_updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
{%- endif -%}
{%- for page in posts_section.pages -%}
    {%- if not page.draft -%}

    {{ page.title | escape_xml | safe }}

    {{ page.permalink | escape_xml | safe }}
    {%- if page.updated -%}
    {{ page.updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
    {%- elif page.date -%}
    {{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
    {%- endif -%}
    {%- if page.date -%}
    {{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
    {%- endif -%}

        {{ page.content | escape_xml | safe }}


    {%- endif -%}
{%- endfor -%}
